"use client";

import Link from "next/link";
import { ArrowLeft, Terminal, Copy, Check } from "lucide-react";
import { useState } from "react";

export default function InstallationPage() {
  const [copied, setCopied] = useState(false);

  const commands = {
    install: `npm install`,
    dev: `npm run dev`,
    build: `npm run build`,
  };

  const copyToClipboard = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error("Failed to copy:", error);
    }
  };

  return (
    <div className="space-y-6">
      <Link
        href="/docs"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to Documentation
      </Link>

      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono font-bold text-[#22e57a] tracking-widest uppercase bg-[rgba(34,229,122,.08)] px-3 py-1 rounded-md border border-[rgba(34,229,122,.1)]">
            Getting Started
          </span>
        </div>
        <h1 className="text-3xl md:text-4xl font-bold font-mono text-[#f2fff8]">
          Installation
        </h1>
        <p className="text-[#93a79d] font-mono text-lg max-w-2xl">
          Set up the project locally and run it with the static IP dataset.
        </p>
      </div>

      <div className="space-y-4">
        {[
          {
            title: "Install dependencies",
            command: commands.install,
          },
          {
            title: "Run in development mode",
            command: commands.dev,
          },
          {
            title: "Build for production",
            command: commands.build,
          },
        ].map((item) => (
          <div
            key={item.title}
            className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.08)] rounded-xl p-6"
          >
            <div className="flex items-center gap-2 mb-3">
              <Terminal size={16} className="text-[#22e57a]" />
              <h2 className="text-lg font-mono font-bold text-[#f2fff8]">
                {item.title}
              </h2>
            </div>
            <div className="relative">
              <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-4 overflow-x-auto font-mono text-sm text-[#7fe9ab]">
                {item.command}
              </pre>
              <button
                onClick={() => copyToClipboard(item.command)}
                className="absolute top-3 right-3 p-1.5 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
              >
                {copied ? (
                  <Check size={14} className="text-[#22e57a]" />
                ) : (
                  <Copy size={14} className="text-[#6f8a7d]" />
                )}
              </button>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.08)] rounded-xl p-6">
        <h3 className="text-sm font-mono font-bold text-[#f2fff8] mb-3">
          Environment note
        </h3>
        <p className="text-[#6f8a7d] font-mono text-sm">
          For GitHub Pages deployment, the app uses the base path /ip-address-database. This is configured in the project build and asset settings.
        </p>
      </div>
    </div>
  );
}
